  "summary": [
    "Early-2026 mortality pace shows 606 deaths/missing by late February, implying continued momentum into March–April.",
    "Historical annual Mediterranean tolls (~2,000–2,500) support the plausibility of reaching 1,000 deaths by end-April if the pace persists.",
    "Updates incorporate strong up signals (pace, seasonal crossing activity, baseline) and a moderating down factor from policy/SAR changes; net effect yields a posterior around 0.69.",
    "Data lag and reporting gaps introduce uncertainty, but the directional signal remains positive for hitting the threshold."
  ],
  "confidence": "high",
  "narrative": "Using the Central Mediterranean reference class, current early-2026 counts imply significant risk of reaching 1,000 deaths by end-April 2026. While historical baselines and the observed pace support this, uncertainties in SAR capacity, weather, and data completeness temper certainty, resulting in a calibrated probability of 0.69.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Central Mediterranean fatalities (IOM Missing Migrants Project) with historical tolls around 2,000–2,500 per year; February counts indicate momentum but not certainty, making 0.75 a plausible starting point."
    },
    "factor_updates": [
      {
        "factor": "Current early-2026 mortality pace (606 by late February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Continued momentum into March–April would push totals toward or beyond 1,000 by end-April."
      },
      {
        "factor": "Seasonal/weather window in spring increasing crossing attempts",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Warmer conditions and improved sea states typically raise crossing attempts and associated fatalities."
      },
      {
        "factor": "Historical annual toll context (~2,000–2,500 per year)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Baseline annual scale makes reaching 1,000 by April feasible if current pace persists."
      },
      {
        "factor": "Policy/SAR capacity and deterrence measures",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improvements in SAR operations or deterrence could reduce fatalities, offsetting the pace signal."
      },
      {
        "factor": "Underreporting and data gaps in Missing Migrants Project",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Data revisions could swing counts up or down; treated as a weak neutral to reflect uncertainty."
      }
    ],
    "synthesis_rationale": "The posterior of 0.69 reflects a deliberate calibration: strong up signals from pace and baseline are tempered by uncertainties around SAR capacity, weather, and data completeness, producing a modest net downward adjustment from the anchor. This yields a calibrated probability in the upper 60s with a reasonably wide but plausible range."
  }
}

{
  "probability": 0.69,
  "range_low": 0.58,
  "range_high": 0.80,
  "summary": [
    "Early 2026 data show a rapid pace of Mediterranean fatalities, with 606 deaths by late February.",
    "If that pace persists into March–April, reaching or exceeding 1,000 deaths by the end of April before May 2026 is plausible given historical annual tolls around 2,000–2,500.",
    "Uncertainty remains due to weather, SAR capacity, policy shifts, and reporting lags, though the calibrated posterior is 69% with an approximate 58–80% uncertainty range.",
    "The anchor and updates collectively support a moderately high probability, but with non-negligible tail risk on the downside."
  ],
  "confidence": "medium",
  "narrative": "Using the strong early-2026 pace alongside a high baseline annual toll, the calibrated probability that the IOM Missing Migrants Project records at least 1,000 Mediterranean deaths before May 2026 is about 69%, with substantial uncertainty due to weather, SAR capacity, and reporting lags.",
  "justification": {
    "anchor": {
      "probability": 0.45,
      "basis": "reference class baseline: annual Mediterranean deaths around 2,000–2,500; from a mid-point of that range and the target window (through April), a starting anchor near 0.45 is reasonable before applying upward updates from current pace."
    },
    "factor_updates": [
      {
        "factor": "Current early-2026 pace (606 deaths by late February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Observed counts imply continuation into March–April, increasing the chance of reaching 1,000 before May."
      },
      {
        "factor": "Historical base-rate context (annual toll ~2,000–2,500)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Even within typical year, the window before May could accumulate enough fatalities if pace continues."
      },
      {
        "factor": "Seasonal/weather window in spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring conditions often see more crossings; more attempts can raise fatalities."
      },
      {
        "factor": "SAR capacity and policy environment",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Decreases or gaps in rescue capacity or deterrence could elevate fatalities; conversely improvements could lower; overall effect uncertain but current trend tilts up."
      },
      {
        "factor": "Reporting completeness and data lag",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Counts may be revised; current momentum remains but potential upward revisions exist."
      }
    ],
    "synthesis_rationale": "All factors collectively tilt toward higher risk of reaching 1,000 by end-April; anchor around mid-point; uncertainties remain due to policy, weather, and data lag. The posterior probability of 0.69 arises from combining strong early pace with substantial but not complete confidence in base rates, and a range of potential offsets."
  }
}

